import json, build
g = json.load(open("../glove80/layout.json"))["layers"][0]
def kc(e):
    if e.get("value") != "&kp": return e.get("value")
    p = e["params"][0]
    v = p["value"]
    if isinstance(v, str) and v == "LS":
        return "LS(" + p["params"][0]["value"] + ")"
    return v
# Glove80 positions: (hand, finger) -> (top, home, bottom)
G = {
 ("L","pinky"):(23,35,47), ("L","ring"):(24,36,48), ("L","middle"):(25,37,49), ("L","index"):(26,38,50),
 ("R","index"):(29,41,59), ("R","middle"):(30,42,60), ("R","ring"):(31,43,61), ("R","pinky"):(32,44,62),
}
SVAL = {
 ("L","pinky"):build.L_PINKY, ("L","ring"):build.L_RING, ("L","middle"):build.L_MIDDLE, ("L","index"):build.L_INDEX,
 ("R","index"):build.R_INDEX, ("R","middle"):build.R_MIDDLE, ("R","ring"):build.R_RING, ("R","pinky"):build.R_PINKY,
}
ROWS = [("top", build.N), ("home", build.C), ("bottom", build.S)]
l0 = build.build_layers()[0]
print(f"{'cell':<18}{'glove80':<16}{'svalboard':<16}")
diverged = []
for (hand, finger), pos in G.items():
    for (rowname, col), p in zip(ROWS, pos):
        a, b = kc(g[p]), l0[SVAL[(hand, finger)]][col]
        a_n = a if a.startswith("KC_") else "KC_" + a
